-- 운영에만 있고 시험 구조에 없던 표 3개 (2026-10-22 운영 information_schema에서 읽기 전용으로 확인)
create table if not exists public.analytics_events (id bigint generated by default as identity primary key, event_type text not null, event_detail jsonb default '{}'::jsonb, staff_name text, created_at timestamptz default now());
create table if not exists public.client_error_logs (id bigint generated by default as identity primary key, created_at timestamptz default now(), app text, message text, stack text, url text, user_role text, user_name text, build text, extra jsonb);
create table if not exists public.as_records (id uuid primary key default gen_random_uuid(), customer_id bigint, customer_name text not null, install_date text, receipt_date text, as_type text, fee_type text default '무상', fee_amount bigint default 0, symptom text, photo_memo text, visit_date text, visit_time text, staff_name text default '마스터', status text default '접수', created_at timestamptz default now(), updated_at timestamptz default now(), is_archived boolean default false);
